const nav=document.querySelector('aside .nav');nav.style.cursor='pointer';nav.onclick=()=>showPage('list');nav.insertAdjacentHTML('afterend','<div id="dashNav" class="dashnav" onclick="showPage(\'dashboard\')">◫ &nbsp;관리 대시보드</div>');
const main=document.querySelector('main');main.id='listPage';const topButton=main.querySelector('.top .primary');topButton.insertAdjacentHTML('beforebegin','<button class="secondary dashboard-shortcut" onclick="showPage(\'dashboard\')">관리 대시보드</button>');main.insertAdjacentHTML('afterend',`<main id="dashboardPage" class="main" hidden><div class="top"><div><div class="eyebrow">AT PROJECT INTELLIGENCE</div><h1>관리 대시보드</h1><p>전체 과제의 현황과 월별 실적을 데이터로 살펴보세요.</p></div><button class="secondary" onclick="showPage('list')">전체 과제 보기</button></div><div class="banner">시연 화면 · 이 브라우저에 저장된 과제만 집계합니다. 예시 데이터는 실제 과제가 아닙니다.</div><div id="dashContent"></div></main>`);
function showPage(page){document.querySelector('#listPage').hidden=page!=='list';document.querySelector('#dashboardPage').hidden=page!=='dashboard';nav.classList.toggle('selected',page==='list');document.querySelector('#dashNav').classList.toggle('selected',page==='dashboard');if(page==='dashboard')renderDashboard();window.scrollTo(0,0)}
function distribution(items,empty){if(!items.length)return `<p class="dash-empty">${empty}</p>`;let max=Math.max(...items.map(a=>a[1]),1);return `<div class="bars">${items.map(([label,count])=>`<div class="barrow"><span>${esc(label)}</span><div class="bartrack"><div class="barfill" style="width:${count/max*100}%"></div></div><strong>${count}</strong></div>`).join('')}</div>`}
function tally(get){let map=new Map();data.filter(x=>!x.archivedAt).forEach(x=>{let labels=get(x);[...new Set(labels.filter(Boolean))].forEach(l=>map.set(l,(map.get(l)||0)+1))});return [...map.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))}
function renderDashboard(){let total=data.filter(x=>!x.archivedAt).length,classified=data.filter(x=>!x.archivedAt).map(x=>({x,p:progress(x)})),late=classified.filter(v=>v.p.label==='지연'),missing=classified.filter(v=>v.p.missing),unplanned=classified.filter(v=>['계획 미등록','계획 재확인'].includes(v.p.label)),normal=classified.filter(v=>v.p.label==='정상'),waiting=classified.filter(v=>v.p.label==='시작 전');let assessed=late.length+normal.length;let teams=tally(x=>[x.team||'팀 미지정']),tech=tally(x=>x.tech||[]),categories=tally(x=>[x.type,...(x.special||[])]);let thisMonth=monthNow();let highlights=[];if(!total)highlights.push('등록된 과제가 없어 분석할 데이터가 없습니다.');else{if(late.length)highlights.push(`누적 지연 과제 ${late.length}건을 우선 검토하세요. 지연 사유와 Catch Up Plan을 과제별로 확인할 수 있습니다.`);else if(assessed)highlights.push(`판정 가능한 ${assessed}건 중 누적 지연 과제가 없습니다.`);if(missing.length)highlights.push(`실적 또는 목표 확인이 필요한 과제가 ${missing.length}건입니다. 미입력은 지연 여부를 판단할 때 0으로 처리하지 않습니다.`);if(unplanned.length)highlights.push(`월별 계획 등록 또는 재확인이 필요한 과제 ${unplanned.length}건은 진행 상태를 판정할 수 없습니다.`);if(teams.length)highlights.push(`과제 수가 가장 많은 팀: ${teams[0][0]} (${teams[0][1]}건). 과제 수는 업무량이나 성과를 뜻하지 않습니다.`)}let focus=[...new Map([...late,...missing,...unplanned].map(v=>[v.x.id,v])).values()].slice(0,8);document.querySelector('#dashContent').innerHTML=`<div class="dash-headline"><span>${esc(thisMonth)} 기준</span><span>월별 목표·실적은 누적 진척률 % 기준</span></div><div class="dash-metrics"><div class="dash-card"><label>전체 과제</label><strong>${total}<small>건</small></strong><p>등록된 전체 과제</p></div><div class="dash-card"><label>누적 지연</label><strong class="red">${late.length}<small>건</small></strong><p>판정 가능 ${assessed}건 중 ${assessed?Math.round(late.length/assessed*100)+'%':'—'}</p></div><div class="dash-card"><label>실적 확인 필요</label><strong class="amber">${missing.length}<small>건</small></strong><p>미입력 월 확인 필요 · 지연과 중복 가능</p></div><div class="dash-card"><label>정상 진행</label><strong class="green">${normal.length}<small>건</small></strong><p>누적 실적이 목표 이상</p></div></div><div class="dash-grid"><section class="dash-panel wide"><div class="section-kicker">PORTFOLIO OVERVIEW</div><h2>진행 상태 분포</h2><p>각 과제의 최신 입력 월 누적 진척률을 비교합니다. 미입력 월은 별도로 표시합니다.</p>${distribution([['정상',normal.length],['지연',late.length],['실적 미입력',missing.filter(v=>!v.p.late).length],['계획 등록·재확인',unplanned.length],['시작 전',waiting.length]],'등록된 과제가 없습니다.')}</section><section class="dash-panel"><div class="section-kicker">TEAM</div><h2>팀별 과제</h2><p>등록 과제 수</p>${distribution(teams,'팀 정보가 없습니다.')}</section><section class="dash-panel"><div class="section-kicker">TECHNOLOGY</div><h2>대상 Tech</h2><p>복수 선택 과제는 각 항목에 포함됩니다.</p>${distribution(tech,'Tech 정보가 없습니다.')}</section><section class="dash-panel"><div class="section-kicker">CLASSIFICATION</div><h2>과제 분류</h2><p>복수 분류가 가능해 합계는 전체 과제 수와 다를 수 있습니다.</p>${distribution(categories,'분류 정보가 없습니다.')}</section><section class="dash-panel wide"><div class="section-kicker">NEEDS ATTENTION</div><h2>확인이 필요한 과제</h2><p>누적 지연, 실적 미입력, 계획 미등록 순으로 최대 8건을 표시합니다.</p>${focus.length?`<div class="attention-list">${focus.map(({x,p})=>`<button class="attention-item" data-project-id="${esc(x.id)}"><span><strong>${esc(x.title)}</strong><small>${esc(x.team||'팀 미지정')} · PM ${esc(x.pm||'미지정')}</small></span><span class="attention-status ${p.label==='지연'?'red':''}">${esc(p.label)}<small>${esc(p.note)}</small></span></button>`).join('')}</div>`:'<div class="dash-empty">현재 확인이 필요한 과제가 없습니다.</div>'}</section><section class="dash-panel wide ai-panel"><div class="ai-heading"><div><div class="section-kicker">INSIGHTS</div><h2>데이터에서 살펴볼 점</h2></div><span class="ai-pill">규칙 기반</span></div><p>입력된 수치로 자동 계산한 관찰 내용입니다.</p><ul class="insight-list">${highlights.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><div class="ai-connection"><div><strong>AI Summary</strong><p>사내 AI 연동 후 과제 내용을 바탕으로 요약, 강점, 취약점 및 개선 방향을 생성할 수 있습니다.</p></div><span>연동 전</span></div></section></div>`;document.querySelectorAll('.attention-item').forEach(btn=>btn.onclick=()=>detail(btn.dataset.projectId))}
document.head.insertAdjacentHTML('beforeend',`<style>.dashboard-shortcut{margin-left:auto;margin-right:10px;white-space:nowrap}@media(max-width:600px){.dashboard-shortcut{font-size:12px;padding:10px}}.dashnav{padding:13px 14px;border-radius:9px;cursor:pointer;margin-top:5px;color:#c9d3e7;font-weight:600}.dashnav.selected,aside .nav.selected{background:#263858;color:white}.nav:not(.selected){background:transparent;color:#c9d3e7}.dash-headline{display:flex;justify-content:space-between;color:#7f8ca0;font-size:13px;margin-bottom:12px}.dash-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.dash-card,.dash-panel{background:white;border:1px solid #e5eaf2;border-radius:12px;box-shadow:0 4px 15px #1c315008}.dash-card{padding:20px}.dash-card label{font-size:13px;font-weight:700;color:#7b899d}.dash-card strong{display:block;font-size:29px;margin:10px 0}.dash-card strong small{font-size:14px;color:#8894a5;margin-left:4px}.dash-card p,.dash-panel p{font-size:13px;line-height:1.6}.red{color:#c44c42!important}.amber{color:#b27b20}.green{color:#24815f}.dash-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:18px}.dash-panel{padding:22px}.dash-panel.wide{grid-column:1/-1}.section-kicker{font-size:11px;letter-spacing:.09em;color:#6d8ac0;font-weight:800}.dash-panel h2{font-size:18px;margin:7px 0 5px}.bars{display:grid;gap:12px;margin-top:22px}.barrow{display:grid;grid-template-columns:minmax(90px,155px) 1fr 35px;gap:10px;align-items:center;font-size:13px;color:#53627a}.barrow strong{text-align:right}.bartrack{height:8px;background:#eef2f8;border-radius:9px;overflow:hidden}.barfill{height:100%;background:#5d86d8;border-radius:9px}.attention-list{margin-top:16px}.attention-item{width:100%;display:flex;justify-content:space-between;text-align:left;gap:15px;border:0;border-top:1px solid #edf1f6;background:white;padding:14px 0;color:#263652}.attention-item:hover{background:#f8faff}.attention-item small{display:block;color:#94a0b1;margin-top:4px;font-size:12px}.attention-status{text-align:right;font-size:13px;font-weight:700;color:#a27125}.attention-status small{font-weight:400}.ai-panel{background:linear-gradient(125deg,#fff,#f5f8ff)}.ai-heading{display:flex;justify-content:space-between;align-items:start}.ai-pill{font-size:12px;border-radius:20px;padding:6px 10px;background:#eaf0ff;color:#5573b5;font-weight:700}.insight-list{padding-left:20px;line-height:1.8;color:#465977;font-size:14px}.ai-connection{border:1px solid #dce6f7;background:#fff;border-radius:9px;padding:15px;display:flex;justify-content:space-between;gap:15px;align-items:center}.ai-connection strong{font-size:14px}.ai-connection span{white-space:nowrap;color:#8190a8;font-size:12px}.dash-empty{padding:20px 0;color:#94a0b1;font-size:13px}@media(max-width:800px){.dash-metrics{grid-template-columns:1fr 1fr}.dash-grid{grid-template-columns:1fr}.dash-panel.wide{grid-column:auto}.dash-headline{gap:10px;flex-wrap:wrap}#dashboardPage .top .secondary{font-size:12px;padding:10px}}</style>`);nav.classList.add('selected');
